import 'package:flutter/material.dart';\nimport '../../../../config/design_system/app_spacing.dart';\nimport '../../../../config/theme/app_colors.dart';\n\nclass DashboardScreen extends StatefulWidget {\n  const DashboardScreen({Key? key}) : super(key: key);\n\n  @override\n  State<DashboardScreen> createState() => _DashboardScreenState();\n}\n\nclass _DashboardScreenState extends State<DashboardScreen> {\n  int _selectedTab = 0;\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('Smart Closet'),\n        elevation: 0,\n        actions: [\n          IconButton(\n            icon: const Icon(Icons.notifications_outlined),\n            onPressed: () {},\n          ),\n          IconButton(\n            icon: const Icon(Icons.person_outlined),\n            onPressed: () {},\n          ),\n        ],\n      ),\n      body: SingleChildScrollView(\n        child: Padding(\n          padding: const EdgeInsets.all(AppSpacing.md),\n          child: Column(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              // Welcome Section\n              Container(\n                padding: const EdgeInsets.all(AppSpacing.md),\n                decoration: BoxDecoration(\n                  gradient: AppColors.luxuryGradient,\n                  borderRadius: BorderRadius.circular(AppSpacing.lg),\n                ),\n                child: Column(\n                  crossAxisAlignment: CrossAxisAlignment.start,\n                  children: [\n                    Text(\n                      'Welcome back!',\n                      style: Theme.of(context).textTheme.headlineSmall?.copyWith(\n                            color: AppColors.white,\n                            fontWeight: FontWeight.w700,\n                          ),\n                    ),\n                    const SizedBox(height: AppSpacing.sm),\n                    Text(\n                      'Ready to find your perfect outfit?',\n                      style: Theme.of(context).textTheme.bodyMedium?.copyWith(\n                            color: AppColors.chrome,\n                          ),\n                    ),\n                  ],\n                ),\n              ),\n              const SizedBox(height: AppSpacing.lg),\n              // Quick Actions\n              Text(\n                'Quick Actions',\n                style: Theme.of(context).textTheme.titleLarge?.copyWith(\n                      fontWeight: FontWeight.w700,\n                    ),\n              ),\n              const SizedBox(height: AppSpacing.md),\n              GridView.count(\n                crossAxisCount: 2,\n                shrinkWrap: true,\n                physics: const NeverScrollableScrollPhysics(),\n                crossAxisSpacing: AppSpacing.md,\n                mainAxisSpacing: AppSpacing.md,\n                childAspectRatio: 1.2,\n                children: [\n                  _buildActionCard(\n                    context,\n                    icon: Icons.add_photo_alternate_outlined,\n                    label: 'Upload Clothes',\n                    onTap: () {},\n                  ),\n                  _buildActionCard(\n                    context,\n                    icon: Icons.event_outlined,\n                    label: 'Select Event',\n                    onTap: () {},\n                  ),\n                  _buildActionCard(\n                    context,\n                    icon: Icons.palette_outlined,\n                    label: 'AI Avatar',\n                    onTap: () {},\n                  ),\n                  _buildActionCard(\n                    context,\n                    icon: Icons.spa_outlined,\n                    label: 'Beauty Tips',\n                    onTap: () {},\n                  ),\n                ],\n              ),\n              const SizedBox(height: AppSpacing.lg),\n              // Recent Recommendations\n              Text(\n                'Recent Recommendations',\n                style: Theme.of(context).textTheme.titleLarge?.copyWith(\n                      fontWeight: FontWeight.w700,\n                    ),\n              ),\n              const SizedBox(height: AppSpacing.md),\n              Container(\n                padding: const EdgeInsets.all(AppSpacing.md),\n                decoration: BoxDecoration(\n                  color: AppColors.darkGrey,\n                  borderRadius: BorderRadius.circular(AppSpacing.lg),\n                  border: Border.all(\n                    color: AppColors.mediumGrey,\n                  ),\n                ),\n                child: Column(\n                  children: [\n                    Icon(\n                      Icons.checkmark_circle_outline,\n                      size: 48,\n                      color: AppColors.chrome,\n                    ),\n                    const SizedBox(height: AppSpacing.md),\n                    Text(\n                      'No recent recommendations',\n                      style: Theme.of(context).textTheme.bodyMedium,\n                    ),\n                    const SizedBox(height: AppSpacing.sm),\n                    Text(\n                      'Start by uploading your wardrobe',\n                      style: Theme.of(context).textTheme.bodySmall?.copyWith(\n                            color: AppColors.chrome,\n                          ),\n                    ),\n                  ],\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n      bottomNavigationBar: BottomNavigationBar(\n        currentIndex: _selectedTab,\n        onTap: (index) => setState(() => _selectedTab = index),\n        items: const [\n          BottomNavigationBarItem(\n            icon: Icon(Icons.home_outlined),\n            label: 'Home',\n          ),\n          BottomNavigationBarItem(\n            icon: Icon(Icons.shopping_bag_outlined),\n            label: 'Wardrobe',\n          ),\n          BottomNavigationBarItem(\n            icon: Icon(Icons.favorite_outline),\n            label: 'Favorites',\n          ),\n          BottomNavigationBarItem(\n            icon: Icon(Icons.settings_outlined),\n            label: 'Settings',\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildActionCard(\n    BuildContext context, {\n    required IconData icon,\n    required String label,\n    required VoidCallback onTap,\n  }) {\n    return GestureDetector(\n      onTap: onTap,\n      child: Container(\n        decoration: BoxDecoration(\n          color: AppColors.darkGrey,\n          borderRadius: BorderRadius.circular(AppSpacing.lg),\n          border: Border.all(\n            color: AppColors.mediumGrey,\n          ),\n        ),\n        child: Column(\n          mainAxisAlignment: MainAxisAlignment.center,\n          children: [\n            Icon(\n              icon,\n              size: 36,\n              color: AppColors.chrome,\n            ),\n            const SizedBox(height: AppSpacing.sm),\n            Text(\n              label,\n              textAlign: TextAlign.center,\n              style: Theme.of(context).textTheme.labelLarge,\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n